mapper.delete:
DELETE FROM artifact
WHERE tenant_id = #{tenantId} AND source_type = #{sourceType}
  AND workitem_id = #{sourceId} AND id = #{id}

mapper.select:
SELECT  FROM artifact
WHERE tenant_id = #{tenantId}
  AND (name = #{usageName} OR name LIKE CONCAT('%/', #{usageName}))
  AND dispatch_id IS NOT NULL
ORDER BY id ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE artifact SET external_exposed = 1, external_share_ref = #{externalShareRef}
WHERE tenant_id = #{tenantId} AND workitem_id = #{workitemId} AND id = #{id}
  AND external_share_ref IS NULL
